	system.perspective.print("updateCheckCalculation() called for %s"%chkItem['chkItemName'])

	chkShtEventId = self.view.custom.chkSht.info.chkShtEventId
	calculation = system.util.jsonDecode(chkItem['calculation'])
	calc = calculation['formulaType']
	formula = calculation['values']
	script = calculation['script']

	chkItems = self.view.custom.chkSht.chkItems

	chkItemPaths = []
 	for k,v  in chkItems.items():
 		chkItemPath = "%s\%s"%(v['chkItemGroupName'], v['chkItemName'])
 		if chkItemPath in formula: chkItemPaths.append(chkItemPath)

	chkItemValues = system.kanoa.utilities.convertDatasetToDict(system.kanoa.quality.event.getAllChkShtItemEventValues(chkShtEventId, chkItemPaths), 'chkItemPath', 'chkItemValue')

#	system.perspective.print("calc = %s"%calc)
#	system.perspective.print("chkItemPaths = %s"%chkItemPaths)
#	system.perspective.print("chkItemValues = %s"%chkItemValues)	

	if calc == 'SCRIPT':
		args = {'productId':self.view.custom.chkSht.info.itemId}
		args['measurements'] = chkItemValues
#		system.perspective.print("func is %s. Args are %s"%(script, args)) #args = {'M09':0.56, 'M01':0.58, 'M02':None, 'M03':0.48, 'M04':None, 'M00':0.6}
		calcValue = kanoaScripts.custom.quality.calculators.executeCalculator(script, args)


	elif calc == 'EVAL':	#This is a custom calculation i.e EVAL(7 + 5 * 4.2/3).	We need to pull out the chkItemNames and replace them with the actual value
		for k,v in chkItemValues.items():
			formula = formula.replace("'" + k + "'", str(v))

#		system.perspective.print("Found item %s with value %s, Formula is now %s "%(chkItem['chkItemName'], chkItemValues[chkItem['chkItemName']], formula))
		try:
			calcValue = eval(formula)
		except:	
			system.perspective.print("error with eval")
			calcValue = None

	else:	#(min, max, avg, etc.)
		if len(chkItemValues) == 0: calcValue = None
		elif calc == 'AVG': calcValue = system.math.mean(chkItemValues.values())
		elif calc == 'STDDEV': calcValue = system.math.standardDeviation(chkItemValues.values())
		elif calc == 'SUM': calcValue = system.math.sum(chkItemValues.values())					
		elif calc == 'MIN': calcValue = system.math.min(chkItemValues.values())
		elif calc == 'MAX': calcValue = system.math.max(chkItemValues.values())
		elif calc == 'RANGE': 	
			try:
				calcValue = system.math.max(chkItemValues.values()) - system.math.min(chkItemValues.values())
			except:
				system.perspective.print("error with range")
				pass
		else: calcValue = None

	system.perspective.print("updateCheckCalculation() returned %s"%calcValue)

	return calcValue

if value is None: return None, "No value passed"

chkItemValueState = 'NO STATE'
chkItemStates[chkItemValueState] = None	#Add a 'NO STATE' key

if chkItemInfo['dataTypeName'] == 'String' and chkItemInfo['pickListName'] == 'Text':
	try:
		pickListValues = system.util.jsonDecode(chkItemInfo['pickListValues'])
		for k, v in pickListValues.items():	
			if value in v:
				chkItemValueState = k
				break
	except:
		pass
elif chkItemInfo['dataTypeName'] in ('Integer', 'Float'):		#Check if entered value is within limits. If we don't find a tolerance spec, we will default to the picklist values
	specs = chkItemInfo['spec']
	spec = system.util.jsonDecode(chkItemInfo['specification'])
	if spec:
		if spec['specType'] == 'setPoint':
			tolerances = spec['setPoint']
			if tolerances['operator'] == '=': tolerances['operator'] = '=='
			valuePass = eval("%f %s %f"%(value, tolerances['operator'], tolerances['value']))	
			specs['lsl'] = value if valuePass else value + 1

		#Check if entered value is within limits
		if specs['uel'] is not None and value > specs['uel']: return None, "Value exceeds Upper Entry Limit. Allowable range is %s to %s"%(specs['lel'], specs['uel'])
		elif specs['lel'] is not None and value < specs['lel']: return None, "Value is below Lower Entry Limit. Allowable range is %s to %s"%(specs['lel'], specs['uel'])

		if specs['lsl'] is not None and value < specs['lsl']: chkItemValueState = 'FAIL'
		elif specs['usl'] is not None and value > specs['usl']: chkItemValueState = 'FAIL'
		elif specs['lcl'] is not None and value < specs['lcl']: chkItemValueState = 'WARNING'
		elif specs['ucl'] is not None and value > specs['ucl']: chkItemValueState = 'WARNING'
		else: chkItemValueState = 'PASS'

if chkItemStates.has_key(chkItemValueState):
	valueState = chkItemStates[chkItemValueState]['chkItemStateId'] if chkItemValueState != 'NO STATE' else None
	msg = None
else:
	valueState = None
	msg = 'Invalid checkItem state configured for this check item. Check the configured picklist options'

return valueState, None
